pid_t session_id;

/* setsid() creates a new session, sets the calling
   process as the session leader, and detaches it
   from any controlling terminal. */

/* Prerequisite: Must not be a Process Group Leader.
   Often preceded by fork() and exit(parent). */

session_id = setsid();

if (session_id == (pid_t)-1) {
    // Failure (EPERM if process is already PGL)
    // Handle error...
}

// Success: session_id equals the calling process's PID.
// The process is now the session leader.
